import { Clock } from '../domain/Clock';
import { OrderRepository } from '../domain/OrderRepository';
import { OrderStatus } from '../domain/OrderStatus';
import { StockReservationService } from '../domain/StockReservationService';
import { OrderDto } from './dtos';
import { toOrderDto } from './OrderDtoMapper';
import { loadOrder } from './OrderLoader';

/** Moves an order one step along placed → paid → packed → shipped → delivered. */
export class AdvanceOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly stock: StockReservationService,
    private readonly clock: Clock,
  ) {}

  execute(orderId: string, target: OrderStatus, context?: ExecuteContextDto): OrderDto {
    const order = loadOrder(this.orders, orderId);
    order.advanceTo(target, this.clock.now());

    if (target === 'shipped') {
      this.stock.dispatch(order.lines);
    }
    this.orders.save(order);
    return toOrderDto(order);
  }
}

export interface ExecuteContextDto {
  readonly requestId?: string;
}

